import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Alchemy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/alchemy.md","filePath":"guide/professions/alchemy.md"}'),n={name:"guide/professions/alchemy.md"};function o(r,e,l,d,c,h){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="alchemy" tabindex="-1">Alchemy <a class="header-anchor" href="#alchemy" aria-label="Permalink to &quot;Alchemy&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/professions/alchemy.html">full design specification</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Alchemy explores simplified principles and reactions through crushing, dissolving, heating, distilling, separating and combining. A laboratory should support meaningful experiments without becoming a chemistry simulator. Results can include oils, powders, salves, inks, solvents and preservatives as well as draughts.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Proposed uses include smoke, adhesives, volatile mixtures, toxins and medical support. A coagulant might reduce bleeding; an analgesic might suppress pain penalties without healing trauma. These are future interactions, not confirmed injury mechanics.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>The Alchemical Journal records observations that can grow into understood formulations. Distillation and Toxicology are examples of concrete technique paths. Material quality, purity, stability and preparation matter; copying a recipe should not reproduce another character’s mastery automatically.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progression and related crafts <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Permalink to &quot;Progression and related crafts&quot;">​</a></h2><p>Skill should improve the range and consistency of work while discoveries open possibilities. <a href="/Syrolands-Public/guide/professions/overview.html">Shared progression and production</a> apply. <a href="/Syrolands-Public/guide/professions/tinkering.html">Tinkering</a> can deliver alchemical payloads and <a href="/Syrolands-Public/guide/professions/tailoring.html">Tailoring</a> can use treatments or dyes. Medical and magical interactions, toxin behavior and counterplay remain open.</p><p><a href="/Syrolands-Public/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/game-design/professions/alchemy.html">Full design specification</a></p><h2 id="magic-materials" tabindex="-1">Magic materials <a class="header-anchor" href="#magic-materials" aria-label="Permalink to &quot;Magic materials&quot;">​</a></h2><p>The <a href="/Syrolands-Public/guide/magic/spellbooks-scrolls-and-reagents.html">magic proposal</a> retains physical reagents and leaves room for Alchemy to process them for spells and Inscription. Recipes and effects are undecided; carrying magical resources still involves loot risk.</p>',13)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
